import { parseFormula } from './formula.js'
import { cellKey, expandRange } from './address.js'

const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (code) => ({ k: 'err', v: code })
const num = (v) => ({ k: 'num', v })
const ZERO = num(0)

const ARITY = { SUM: [1, Infinity], MIN: [1, Infinity], MAX: [1, Infinity], COUNT: [1, Infinity], AVG: [1, Infinity], ABS: [1, 1], IF: [3, 3] }

/** True when a tree has a misplaced range or a known call with a wrong argument count. */
function staticBad(n, direct = false) {
  switch (n.t) {
    case 'range': return !direct
    case 'un': return staticBad(n.x)
    case 'bin': return staticBad(n.l) || staticBad(n.r)
    case 'call': {
      const ar = ARITY[n.name]
      if (ar && (n.args.length < ar[0] || n.args.length > ar[1])) return true
      return n.args.some((a) => staticBad(a, true))
    }
  }
  return false
}

function literal(content) {
  if (content === '') return ZERO
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
  if (ERRORS.includes(content)) return err(content)
  return { k: 'text', v: content }
}

export function evaluateSheet(cells) {
  const memo = new Map()
  const active = new Set()

  function cellValue(addr) {
    const key = cellKey(addr)
    if (memo.has(key)) return memo.get(key)
    const c = cells.get(key)
    if (!c) return ZERO
    if (active.has(key)) return err('#CYCLE!')
    active.add(key)
    let v
    if (c.content[0] === '=') {
      const tree = parseFormula(c.content.slice(1))
      v = !tree || staticBad(tree) ? err('#ERR!') : ev(tree)
    } else v = literal(c.content)
    active.delete(key)
    memo.set(key, v)
    return v
  }

  function toNum(v) {
    if (v.k === 'num') return v.v
    if (v.k === 'bool') return v.v ? 1 : 0
    return null
  }

  function arith(op, a, b) {
    if (a.k === 'err') return a
    if (b.k === 'err') return b
    const x = toNum(a), y = toNum(b)
    if (x === null || y === null) return err('#VALUE!')
    let r
    if (op === '+') r = x + y
    else if (op === '-') r = x - y
    else if (op === '*') r = x * y
    else if (op === '/') { if (y === 0) return err('#DIV/0!'); r = x / y }
    else r = Math.pow(x, y)
    return Number.isFinite(r) ? num(r) : err('#DIV/0!')
  }

  const rank = { num: 0, text: 1, bool: 2 }
  function compare(op, a, b) {
    if (a.k === 'err') return a
    if (b.k === 'err') return b
    let c
    if (a.k !== b.k) c = rank[a.k] - rank[b.k]
    else if (a.k === 'text') c = a.v === b.v ? 0 : cmpCodePoints(a.v, b.v)
    else { const x = Number(a.v), y = Number(b.v); c = x < y ? -1 : x > y ? 1 : 0 }
    const r = op === '=' ? c === 0 : op === '<>' ? c !== 0 : op === '<' ? c < 0 : op === '<=' ? c <= 0 : op === '>' ? c > 0 : c >= 0
    return { k: 'bool', v: r }
  }
  function cmpCodePoints(s, t) {
    const a = Array.from(s), b = Array.from(t)
    for (let i = 0; i < a.length && i < b.length; i++) {
      const d = a[i].codePointAt(0) - b[i].codePointAt(0)
      if (d) return d
    }
    return a.length - b.length
  }

  /** Argument values in order, ranges expanded; returns an array of values. */
  function argValues(args) {
    const out = []
    for (const a of args) {
      if (a.t === 'range') {
        if (!a.a || !a.b) out.push(err('#REF!'))
        else for (const ad of expandRange(a.a, a.b)) out.push(cellValue(ad))
      } else out.push(ev(a))
    }
    return out
  }

  function single(a) {
    if (a.t !== 'range') return ev(a)
    if (!a.a || !a.b) return err('#REF!')
    const l = expandRange(a.a, a.b)
    return l.length === 1 ? cellValue(l[0]) : err('#ERR!')
  }

  function call(n) {
    const { name, args } = n
    if (!ARITY[name]) return err('#NAME?')
    if (name === 'IF') {
      const c = single(args[0])
      if (c.k === 'err') return c
      if (c.k === 'text') return err('#VALUE!')
      return single(toNum(c) !== 0 ? args[1] : args[2])
    }
    if (name === 'ABS') {
      const v = single(args[0])
      if (v.k === 'err') return v
      const x = toNum(v)
      return x === null ? err('#VALUE!') : num(Math.abs(x))
    }
    const vals = argValues(args)
    const e = vals.find((v) => v.k === 'err')
    if (e) return e
    if (name === 'COUNT') return num(vals.filter((v) => v.k === 'num').length)
    if (vals.some((v) => v.k === 'text')) return err('#VALUE!')
    const xs = vals.map(toNum)
    let r
    if (name === 'SUM') r = xs.reduce((a, b) => a + b, 0)
    else if (name === 'MIN') r = xs.reduce((a, b) => (b < a ? b : a))
    else if (name === 'MAX') r = xs.reduce((a, b) => (b > a ? b : a))
    else {
      if (xs.length === 0) return err('#DIV/0!')
      r = xs.reduce((a, b) => a + b, 0) / xs.length
    }
    return Number.isFinite(r) ? num(r) : err('#DIV/0!')
  }

  function ev(n) {
    switch (n.t) {
      case 'num': return num(n.v)
      case 'bool': return { k: 'bool', v: n.v }
      case 'ref': return n.addr ? cellValue(n.addr) : err('#REF!')
      case 'range': return err('#ERR!')
      case 'un': {
        const v = ev(n.x)
        if (v.k === 'err') return v
        const x = toNum(v)
        if (x === null) return err('#VALUE!')
        return num(n.op === '-' ? -x : x)
      }
      case 'bin': {
        const a = ev(n.l)
        if (a.k === 'err') return a
        const b = ev(n.r)
        return ['+', '-', '*', '/', '^'].includes(n.op) ? arith(n.op, a, b) : compare(n.op, a, b)
      }
      case 'call': return call(n)
    }
  }

  const result = new Map()
  for (const [key, c] of cells) result.set(key, cellValue(c.addr))
  return result
}

export function formatValue(v) {
  switch (v.k) {
    case 'num': return String(Number(v.v.toPrecision(10)))
    case 'bool': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}
