/** Cell addresses: column index 1..702 (A..Z, AA..ZZ), row 1..999. */
export function parseAddress(word) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(word)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const L = m[1].toUpperCase()
  const col = L.length === 1 ? L.charCodeAt(0) - 64 : 26 + (L.charCodeAt(0) - 65) * 26 + (L.charCodeAt(1) - 64)
  return { col, row }
}

export const cellKey = (a) => a.col * 1000 + a.row

export function addressText(a) {
  const c = a.col
  const letters = c <= 26 ? String.fromCharCode(64 + c)
    : String.fromCharCode(65 + Math.floor((c - 27) / 26)) + String.fromCharCode(65 + ((c - 27) % 26))
  return letters + a.row
}

/** Every address in a range, ascending column then row. */
export function expandRange(a, b) {
  const out = []
  const c1 = Math.min(a.col, b.col), c2 = Math.max(a.col, b.col)
  const r1 = Math.min(a.row, b.row), r2 = Math.max(a.row, b.row)
  for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) out.push({ col: c, row: r })
  return out
}

/** Distinct in-range addresses a parsed formula names, sorted. */
export function collectRefs(tree) {
  const seen = new Map()
  const add = (a) => seen.set(cellKey(a), a)
  const walk = (n) => {
    switch (n.t) {
      case 'ref': if (n.addr) add(n.addr); break
      case 'range': if (n.a && n.b) expandRange(n.a, n.b).forEach(add); break
      case 'un': walk(n.x); break
      case 'bin': walk(n.l); walk(n.r); break
      case 'call': n.args.forEach(walk); break
    }
  }
  walk(tree)
  return [...seen.values()].sort((x, y) => x.col - y.col || x.row - y.row)
}
