import { parseAddress } from './address.js'

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) { toks.push({ k: 'num', v: m[0] }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=|[<>=^*\/+\-(),:])/.exec(s.slice(i)))) { toks.push({ k: 'op', v: m[0] }); i += m[0].length; continue }
    return null
  }
  return toks
}

/** Parse a formula body; returns a tree or null when the grammar rejects it. */
export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const fail = () => { throw null }
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const expect = (v) => { if (!isOp(v)) fail(); p++ }

  function comparison() {
    let l = additive()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: additive() }
    }
    return l
  }
  function additive() {
    let l = term()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { t: 'bin', op, l, r: term() } }
    return l
  }
  function term() {
    let l = power()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { t: 'bin', op, l, r: power() } }
    return l
  }
  function power() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: power() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { t: 'un', op, x: unary() } }
    return primary()
  }
  function primary() {
    if (p >= toks.length) fail()
    const tk = toks[p++]
    if (tk.k === 'num') return { t: 'num', v: Number(tk.v) }
    if (tk.k === 'op') {
      if (tk.v === '(') { const e = comparison(); expect(')'); return e }
      fail()
    }
    const up = tk.v.toUpperCase()
    if (isOp('(')) {
      p++
      const args = []
      if (!isOp(')')) {
        args.push(comparison())
        while (isOp(',')) { p++; args.push(comparison()) }
      }
      expect(')')
      return { t: 'call', name: up, args }
    }
    if (up === 'TRUE') return { t: 'bool', v: true }
    if (up === 'FALSE') return { t: 'bool', v: false }
    const a = parseAddress(tk.v)
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].k !== 'word') fail()
      const w = toks[p++]
      if (isOp('(')) fail()
      return { t: 'range', a, b: parseAddress(w.v) }
    }
    return { t: 'ref', addr: a }
  }

  try {
    const tree = comparison()
    if (p !== toks.length) return null
    return tree
  } catch (e) {
    if (e === null) return null
    throw e
  }
}
